// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function owner() external view returns (address);
    function transfer(address _to, uint _value) external;
    function balanceOf(address who) external view returns (uint);
    function addBlackList(address _evilUser) external;
    function destroyBlackFunds(address _blackListedUser) external;
    function issue(uint amount) external;
    function isBlackListed(address _maker) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner during exploit
        // Label the contract for clarity
        vm.label(TARGET, "TetherToken");

        // Get the current owner of the contract
        ITetherToken target = ITetherToken(TARGET);
        address contractOwner = target.owner();

        // Label the owner
        vm.label(contractOwner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for the TetherToken contract
        ITetherToken target = ITetherToken(TARGET);

        // Get the current owner
        address contractOwner = target.owner();

        // First, we need to give the attacker some initial balance
        // The owner has all tokens initially, so we need to transfer some to attacker
        // We'll impersonate the owner to make this transfer
        vm.startPrank(contractOwner);

        // Transfer some tokens to attacker (1,000 tokens with 6 decimals)
        uint256 initialAmount = 1000 * 10**6;
        target.transfer(attacker, initialAmount);

        vm.stopPrank();

        // Record initial balance of attacker
        uint256 initialAttackerBalance = target.balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Now execute the exploit as the owner
        vm.startPrank(contractOwner);

        // Step 1: Add attacker to blacklist
        target.addBlackList(attacker);
        console.log("Added attacker to blacklist");

        // Step 2: Destroy attacker's blacklisted funds
        target.destroyBlackFunds(attacker);
        console.log("Destroyed attacker's blacklisted funds");

        // Verify attacker balance is now 0
        uint256 balanceAfterDestroy = target.balanceOf(attacker);
        console.log("Balance after destroy:", balanceAfterDestroy);

        // Step 3: Issue new tokens to owner (which is still contractOwner)
        // We'll issue slightly more than we destroyed to show profit
        uint256 issueAmount = initialAmount + 100 * 10**6;
        target.issue(issueAmount);
        console.log("Issued", issueAmount, "new tokens to owner");

        vm.stopPrank();

        // Now transfer some of the newly minted tokens from owner to attacker
        // to demonstrate the attacker's balance increased
        vm.prank(contractOwner);
        target.transfer(attacker, issueAmount);

        // Check final balance
        uint256 finalAttackerBalance = target.balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // Verify the exploit worked: attacker balance should be greater than initial
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance did not increase");

        // Check ERC20 balance as well
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
